      if (!mounted) return;
      setState(() { entries = raw == null ? [] : (jsonDecode(raw) as List).map((e) => Entry.fromJson(Map<String, dynamic>.from(e as Map))).toList(); friends = f == null ? [] : List<String>.from(jsonDecode(f) as List); });
